 6 | pragma solidity ^0.8.0;
 7 | 
 8 | import './interfaces/IERC20.sol';
 9 | import './interfaces/ILPTokenMaster.sol';
10 | import './interfaces/ILendingPair.sol';
11 | import './interfaces/IController.sol';
12 | import './interfaces/IRewardDistribution.sol';
13 | import './interfaces/IInterestRateModel.sol';
14 | 
15 | import './external/Math.sol';
16 | import './external/Ownable.sol';
17 | import './external/Address.sol';
18 | import './external/Clones.sol';
19 | import './external/ERC20.sol';
20 | 
21 | import './TransferHelper.sol';
22 | 
23 | contract LendingPair is TransferHelper {
24 | 
25 |   // Prevents division by zero and other undesirable behaviour
26 |   uint public constant MIN_RESERVE = 1000;
27 | 
28 |   using Address for address;
29 |   using Clones for address;
30 | 
31 |   mapping (address => mapping (address => uint)) public debtOf;
32 |   mapping (address => mapping (address => uint)) public accountInterestSnapshot;
33 |   mapping (address => uint) public cumulativeInterestRate; // 100e18 = 100%
34 |   mapping (address => uint) public totalDebt;
35 |   mapping (address => IERC20) public lpToken;
36 | 
37 |   IController public controller;
38 |   address public tokenA;
39 |   address public tokenB;
40 |   uint public lastBlockAccrued;
41 | 
42 |   event Liquidation(
43 |     address indexed account,
44 |     address indexed repayToken,
45 |     address indexed supplyToken,
46 |     uint repayAmount,
47 |     uint supplyAmount
48 |   );
49 | 
50 |   event Deposit(address indexed account, address indexed token, uint amount);
51 |   event Withdraw(address indexed token, uint amount);
52 |   event Borrow(address indexed token, uint amount);
53 |   event Repay(address indexed account, address indexed token, uint amount);
